{"path": "durations.py", "content": "import re

# Units in the required order h, m, s, each optional; parts may be separated by spaces.
_PATTERN = re.compile(r'(?:([0-9]+)h)?(?: *([0-9]+)m)?(?: *([0-9]+)s)?')


def parse_duration(text):
    """See SPEC.md."""
    if not text or text[0] == ' ' or text[-1] == ' ':
        raise ValueError(f'invalid duration: {text!r}')
    match = _PATTERN.fullmatch(text)
    if match is None or all(g is None for g in match.groups()):
        raise ValueError(f'invalid duration: {text!r}')
    hours, minutes, seconds = (int(g) if g is not None else 0 for g in match.groups())
    return hours * 3600 + minutes * 60 + seconds
